#include <iostream>
#include <string_view>

// Demonstrates non-constant pointer to constant data (string traversal)
void printWithConstDataPointer(const char *sPtr) {
    for (; *sPtr != '\0'; ++sPtr) {
        std::cout << *sPtr;
    }
    std::cout << '\n';
}

// C++17 idiomatic string_view alternative
void printWithView(std::string_view sv) {
    for (char ch : sv) {
        std::cout << ch;
    }
    std::cout << '\n';
}

int main() {
    int a = 10;
    int b = 20;

    // 1. Non-constant pointer to constant data
    const int *ptrToConst = &a;
    std::cout << "ptrToConst reads: " << *ptrToConst << '\n';
    ptrToConst = &b; // OK: pointer itself can change
    std::cout << "ptrToConst redirected: " << *ptrToConst << '\n';

    // 2. Constant pointer to non-constant data
    int * const constPtr = &a;
    *constPtr = 15; // OK: target data can change
    std::cout << "constPtr modified a: " << a << '\n';
    // constPtr = &b; // Compiler error: cannot modify const pointer

    // 3. Constant pointer to constant data
    const int * const fixedAll = &b;
    std::cout << "fixedAll reads: " << *fixedAll << '\n';
    // *fixedAll = 25; // Compiler error
    // fixedAll = &a;  // Compiler error

    // Character printing demonstrations
    char message[] = "C++ const pointer demo";
    printWithConstDataPointer(message);
    printWithView(message);

    return 0;
}

#include <iostream>
#include <iomanip>
#include <utility>

// Swap using pointer dereferencing (Deitel C-style mechanism)
void swapByPointer(int *element1Ptr, int *element2Ptr) {
    int hold = *element1Ptr;
    *element1Ptr = *element2Ptr;
    *element2Ptr = hold;
}

// Bubble sort receiving constant pointer to non-constant array data
void bubbleSort(int * const array, const std::size_t size) {
    for (std::size_t pass = 0; pass < size - 1; ++pass) {
        for (std::size_t j = 0; j < size - 1; ++j) {
            if (array[j] > array[j + 1]) {
                swapByPointer(&array[j], &array[j + 1]);
            }
        }
    }
}

void printArray(const int * const array, const std::size_t size) {
    for (std::size_t i = 0; i < size; ++i) {
        std::cout << std::setw(4) << array[i];
    }
    std::cout << '\n';
}

int main() {
    constexpr std::size_t SIZE = 10;
    int a[SIZE] = { 2, 6, 4, 8, 10, 12, 89, 68, 45, 37 };

    std::cout << "Data items in original order\n";
    printArray(a, SIZE);

    bubbleSort(a, SIZE);

    std::cout << "Data items in ascending order\n";
    printArray(a, SIZE);

    return 0;
}
